INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('476059630', '평균 평점 4.4점, 리뷰 5개의 그로토는 조용하고 아늑한 분위기에서 감각적인 인테리어를 즐길 수 있는 카페입니다. 자리 간격이 넓고 한적해 오래 앉아 이야기하거나 예쁜 사진을 남기기 좋습니다.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('1260273250', '아이들이 신나게 놀 수 있고 부모님이 앉아 쉴 자리도 충분한 깔끔한 공간입니다. 숙대입구역에서 가까워 접근성이 좋지만 주말에는 대기가 있을 수 있습니다.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('922091993', '평균 평점 4.5점의 비파티세리 공덕점은 아기자기하고 아늑한 분위기 속에서 눈과 입이 즐거운 디저트를 맛볼 수 있는 곳이에요. 달지 않고 부담이 없어 포장하기에도 좋으니 좌석이 많지 않아 일찍 방문해 보세요.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('1941860892', '평균 평점 4.3점, 리뷰 5개의 서울형키즈카페 용산구청파동점은 넓고 깨끗한 공간에서 아이들이 안전하게 놀 수 있어 부모님들이 편하게 쉴 수 있는 곳입니다. 친절한 직원분들이 아이들을 잘 챙겨주어 가족 모임 장소로 만족스럽다는 평이 많습니다.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('1201355052', '평균 평점 4.2점의 스타벅스 공덕점은 역과 가까워 찾기 쉽고 자리가 넓어 모임이나 작업하기 편해요. 여럿이 앉을 수 있는 큰 테이블과 많은 콘센트가 있어 이용하기 좋습니다.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('1447732810', '진한 원두 향과 훌륭한 커피 맛을 즐길 수 있는 곳이에요. 넓고 천장이 높아 개방감 있는 공간에서 편안한 시간을 보낼 수 있어요.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('27494588', '공덕역에서 가깝고 깔끔한 분위기에서 쫄깃한 베이글을 즐길 수 있는 곳입니다. 평점 4.5점의 리뷰 5개가 말해주듯, 친절한 직원들과 함께 편안한 시간을 보낼 수 있습니다.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('1419437580', '평균 평점 4.4점의 영앤도터스는 밝고 친절한 직원들과 함께 편안한 인테리어를 즐길 수 있는 곳입니다. 넓은 테이블과 잘 터지는 와이파이 덕분에 노트북 작업하기 좋고, 낮에는 채광이 좋아 기분 좋은 시간을 보낼 수 있습니다.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
INSERT INTO place_descriptions (place_id, description, review_count, generated_at) VALUES ('1963225278', '평균 평점 4.4점, 리뷰 5개가 있는 키하라는 편안한 동네 분위기 속에서 잔잔한 음악과 함께 대화하기 좋은 아담한 카페입니다. 친절한 사장님의 따뜻한 응대 덕분에 혼자 와서 책을 읽기에도 좋습니다.', 5, NOW()) ON DUPLICATE KEY UPDATE description = VALUES(description), review_count = VALUES(review_count), generated_at = VALUES(generated_at);
